678:     public function get_order_weight($order): int
679:     {
680:         /**
681:          * Get WooCommerce weight unit
682:          */
683:         $min_weight = apply_filters('woo_lithuaniapost_admin_util_get_min_weight', '');
684: 
685:         $total_weight = 0;
686: 
687:         foreach ($order->get_items() as $item_id => $product_item) {
688:             $quantity = $product_item->get_quantity(); // get quantity
689:             $product = $product_item->get_product(); // get the WC_Product object
690:             $product_weight = $product->get_weight(); // get the product weight
691:             if ($product_weight) {
692:                 // Add the line item weight to the total weight calculation
693:                 $total_weight += max(floatval($product_weight * $quantity), $min_weight);
694:             } else {
695:                 $total_weight += $min_weight;
696:             }
697:         }
698:         return intval(ceil(apply_filters('woo_lithuaniapost_admin_util_convert_to_grams', $total_weight)));
699:     }
